using System.Text.Json;

namespace ControlHome.Connectors.Abstractions;

/// <summary>Commands for one device, delivered together (a connector may send them in one vendor request).</summary>
/// <param name="ExternalDeviceId">The device's <see cref="DiscoveredDevice.ExternalId"/>.</param>
/// <param name="Commands">At least one, applied in order.</param>
/// <param name="IdempotencyKey">
/// Unique per user action (generated by the command service when the client sends none). A connector that sees the same
/// key twice rejects the second batch with <see cref="CommandRejectionCodes.Duplicate"/>: at-most-once delivery.
/// </param>
public sealed record DeviceCommandBatch(string ExternalDeviceId, IReadOnlyList<DeviceCommand> Commands, string IdempotencyKey);

/// <summary>One command of a batch.</summary>
/// <param name="EndpointKey">The endpoint's <see cref="DiscoveredEndpoint.Key"/>.</param>
/// <param name="CapabilityId">A capability bound to that endpoint.</param>
/// <param name="Command">A command of that capability (e.g. <c>setLevel</c>).</param>
/// <param name="Arguments">The arguments object (already validated); an empty object when the command takes none.</param>
public sealed record DeviceCommand(string EndpointKey, string CapabilityId, string Command, JsonElement Arguments);

/// <summary>The result of <see cref="IConnectorRuntime.ExecuteAsync"/>: <see cref="Accepted"/>, <see cref="Completed"/> or <see cref="Rejected"/>.</summary>
public abstract record CommandOutcome
{
    private CommandOutcome()
    {
    }

    public static CommandOutcome AcceptedOutcome { get; } = new Accepted();

    public static CommandOutcome CompletedOutcome { get; } = new Completed();

    public static CommandOutcome Reject(string code, string message) => new Rejected(code, message);

    /// <summary>The device took the command; the result arrives as a state report (confirmation per the command's mode).</summary>
    public sealed record Accepted : CommandOutcome;

    /// <summary>The command is done (and its new state already reported).</summary>
    public sealed record Completed : CommandOutcome;

    /// <summary>The command was not executed.</summary>
    /// <param name="Code">A <see cref="CommandRejectionCodes"/> value (or a connector-specific snake_case code).</param>
    /// <param name="Message">A short English explanation for logs and the audit trail; never secrets.</param>
    public sealed record Rejected(string Code, string Message) : CommandOutcome;
}

/// <summary>Standard <see cref="CommandOutcome.Rejected.Code"/> values.</summary>
public static class CommandRejectionCodes
{
    /// <summary>The batch's idempotency key was already used: the command was not executed again.</summary>
    public const string Duplicate = "duplicate";

    /// <summary>A safety-critical command came without an idempotency key.</summary>
    public const string IdempotencyRequired = "idempotency_required";

    public const string UnknownDevice = "unknown_device";

    public const string UnknownEndpoint = "unknown_endpoint";

    /// <summary>The endpoint does not have the capability, or the capability has no such command.</summary>
    public const string UnsupportedCommand = "unsupported_command";

    public const string InvalidArguments = "invalid_arguments";

    /// <summary>The device or the vendor service cannot be reached, or the runtime is not running.</summary>
    public const string Unavailable = "unavailable";

    /// <summary>The device refused (e.g. remote control disabled on an appliance).</summary>
    public const string Refused = "refused";
}
